CREATE OR REPLACE FUNCTION public.generate_unique_handle(_seed text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  base text;
  candidate text;
  i int := 0;
begin
  base := regexp_replace(lower(coalesce(_seed, 'member')), '[^a-z0-9]+', '', 'g');
  if length(base) < 3 then base := base || 'member'; end if;
  base := left(base, 20);
  candidate := base;
  while not public.is_handle_available(candidate) loop
    i := i + 1;
    candidate := left(base, 20) || i::text;
    exit when i > 9999;
  end loop;
  return candidate;
end;
$function$

CREATE OR REPLACE FUNCTION public.identity_event_chain()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare owner_id uuid;
begin
  if TG_OP <> 'INSERT' then raise exception 'identity_events_append_only'; end if;
  -- Serialize the chain on the identity row, including the first event.
  select user_id into owner_id from public.identity_links where id = NEW.link_id for update;
  if owner_id is null or owner_id <> NEW.user_id then raise exception 'identity_event_owner_mismatch'; end if;
  select event_hash into NEW.prev_hash from public.identity_link_events where link_id = NEW.link_id order by id desc limit 1;
  NEW.event_hash := public.digest(coalesce(NEW.prev_hash, ''::bytea) || convert_to(
    jsonb_build_object('link_id',NEW.link_id,'user_id',NEW.user_id,'event',NEW.event,'actor',NEW.actor,
      'ip_hash',encode(NEW.ip_hash,'hex'),'ua_hash',encode(NEW.ua_hash,'hex'),
      'created_at',to_char(NEW.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::text,'UTF8'),'sha256');
  return NEW;
end $function$

CREATE OR REPLACE FUNCTION public.identity_owner_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if NEW.user_id <> OLD.user_id or NEW.issuer <> OLD.issuer or NEW.provider_sub <> OLD.provider_sub then
    raise exception 'identity_owner_immutable';
  end if;
  return NEW;
end $function$

CREATE OR REPLACE FUNCTION public.log_qr_scan(_tracked_qr_id uuid, _device text DEFAULT NULL::text, _country text DEFAULT NULL::text, _browser text DEFAULT NULL::text, _os text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare recent int;
begin
  if _tracked_qr_id is null then return; end if;

  select count(*) into recent
    from public.qr_scans
   where tracked_qr_id = _tracked_qr_id
     and scanned_at > now() - interval '1 minute';

  if recent >= 60 then return; end if;

  insert into public.qr_scans (tracked_qr_id, device, country, browser, os)
  values (_tracked_qr_id, left(_device, 20), left(_country, 2), left(_browser, 20), left(_os, 20));
end;
$function$

CREATE OR REPLACE FUNCTION public.manage_short_link(_token text, _action text, _target_url text DEFAULT NULL::text, _is_active boolean DEFAULT NULL::boolean, _expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _slug text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  row public.tracked_qrs;
begin
  select * into row from public.tracked_qrs where dashboard_token = _token limit 1;
  if row.id is null then
    raise exception 'Dashboard not found';
  end if;

  if _action = 'update_target' then
    if _target_url is null or length(_target_url) < 3 then
      raise exception 'Invalid target url';
    end if;
    update public.tracked_qrs set target_url = _target_url, updated_at = now() where id = row.id;
  elsif _action = 'set_active' then
    update public.tracked_qrs set is_active = coalesce(_is_active, true), updated_at = now() where id = row.id;
  elsif _action = 'set_expiry' then
    update public.tracked_qrs set expires_at = _expires_at, updated_at = now() where id = row.id;
  elsif _action = 'regenerate_slug' then
    if _slug is null then raise exception 'Missing slug'; end if;
    update public.tracked_qrs set slug = lower(_slug), updated_at = now() where id = row.id;
  elsif _action = 'delete' then
    delete from public.tracked_qrs where id = row.id;
  else
    raise exception 'Unknown action %', _action;
  end if;

  return jsonb_build_object('ok', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.patch_profile_draft(p_user_id uuid, p_space text, p_fields jsonb, p_prefs jsonb, p_drop_prefs text[])
 RETURNS TABLE(revision bigint, published_revision bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_fields jsonb := coalesce(p_fields, '{}'::jsonb);
  v_prefs jsonb := coalesce(p_prefs, '{}'::jsonb);
begin
  if p_space not in ('verified', 'alias') then
    raise exception 'draft_space_invalid';
  end if;
  if jsonb_typeof(v_fields) <> 'object' or jsonb_typeof(v_prefs) <> 'object' then
    raise exception 'validation: draft patch must be an object';
  end if;

  return query
    update public.profile_drafts d
       set payload = (
             (case when jsonb_typeof(d.payload) = 'object' then d.payload else '{}'::jsonb end)
             || (v_fields - 'displayPrefs')
           ) || jsonb_build_object(
             'displayPrefs',
             ((case when jsonb_typeof(d.payload -> 'displayPrefs') = 'object'
                    then d.payload -> 'displayPrefs' else '{}'::jsonb end)
               - coalesce(p_drop_prefs, '{}'::text[]))
             || v_prefs
           ),
           revision = d.revision + 1,
           updated_at = now()
     where d.user_id = p_user_id and d.space = p_space
    returning d.revision, d.published_revision;

  if not found then
    raise exception 'draft_not_found';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.profiles_handle_namespace_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.username is distinct from coalesce(old.username, null) then
    perform public.assert_handle_namespace_free(new.username, new.id);
  end if;
  if new.subdomain_alias is distinct from coalesce(old.subdomain_alias, null) then
    perform public.assert_handle_namespace_free(new.subdomain_alias, new.id);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.queue_presence_broadcast()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare owner uuid; event uuid; canvas text; message text;
begin
 if tg_table_name='profile_questions' then
  if not new.published or new.answer is null or new.is_quarantined then return new;end if;
  owner:=new.owner_id;event:=new.id;canvas:=new.space;message:=new.body||E'\n\n'||new.answer;
 else
  owner:=new.user_id;event:=new.id;canvas:=new.space;
  if new.status_type<>'micro_text' then return new;end if;
  message:=new.content_payload->>'text';
 end if;
 if not public.rout_broadcast_event_allowed(owner,event,canvas) then return new;end if;
 insert into public.presence_broadcast_jobs(user_id,event_id,space,provider,payload)
 select owner,event,canvas,provider,jsonb_build_object('text',left(message,4000)) from public.user_integrations
 where user_id=owner and provider in ('omnicast_mastodon','omnicast_bluesky','omnicast_telegram','omnicast_webhook')
 and connection_status='connected' and coalesce(status_json->'broadcastSpaces','[]'::jsonb) ? canvas
 on conflict(user_id,event_id,provider) do nothing;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.reserve_recovery_email()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if exists (select 1 from public.account_email_changes c where lower(c.old_email)=lower(new.email)
      and c.user_id<>new.id and c.recovery_until>now()) then
    raise exception 'email_reserved_for_recovery';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.rotate_oauth_refresh(old_hash text, target_client text, new_hash text)
 RETURNS TABLE(result text, user_id uuid, subject text, scopes text[], family_id uuid, auth_time timestamp with time zone, acr text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare old public.oauth_refresh_tokens%rowtype;
begin
  select * into old from public.oauth_refresh_tokens t where t.token_hash=old_hash and t.client_id=target_client for update;
  if not found then return query select 'invalid'::text,null::uuid,null::text,null::text[],null::uuid,null::timestamptz,null::text; return; end if;
  -- Family-wide advisory lock prevents a concurrent descendant issuance from escaping revocation.
  perform pg_advisory_xact_lock(hashtextextended(old.family_id::text,0));
  if old.used_at is not null then
    update public.oauth_refresh_tokens t set revoked_at=coalesce(t.revoked_at,now()) where t.family_id=old.family_id;
    update public.oauth_access_tokens t set revoked_at=coalesce(t.revoked_at,now()) where t.family_id=old.family_id;
    return query select 'reuse'::text,null::uuid,null::text,null::text[],old.family_id,null::timestamptz,null::text; return;
  end if;
  if old.revoked_at is not null or old.expires_at<=now()
    or exists(select 1 from public.oauth_refresh_tokens t where t.family_id=old.family_id and t.revoked_at is not null)
    or not exists(select 1 from public.oauth_consents c where c.user_id=old.user_id and c.client_id=target_client and c.revoked_at is null and 'offline_access'=any(c.scopes))
    or not exists(select 1 from public.users u where u.id=old.user_id and not u.is_disabled and u.account_status='active')
    or not exists(select 1 from public.oauth_clients c where c.client_id=target_client and c.status='active') then
    return query select 'invalid'::text,null::uuid,null::text,null::text[],old.family_id,null::timestamptz,null::text; return;
  end if;
  update public.oauth_refresh_tokens t set used_at=now() where t.id=old.id;
  insert into public.oauth_refresh_tokens(family_id,token_hash,client_id,user_id,scopes,expires_at,subject,auth_time,acr)
  values(old.family_id,new_hash,target_client,old.user_id,old.scopes,old.expires_at,old.subject,old.auth_time,old.acr);
  return query select 'ok'::text,old.user_id,old.subject,old.scopes,old.family_id,old.auth_time,old.acr;
end $function$

CREATE OR REPLACE FUNCTION public.rout_agent_provision_workspace(p_client_id text, p_name text, p_slug text, p_description text, p_token_hash text)
 RETURNS TABLE(workspace_id uuid, slug text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := public.rout_current_user_id();
  v_open integer;
  v_ws uuid;
  v_now timestamptz := now();
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  perform pg_advisory_xact_lock(hashtext('agent_provision:' || v_uid::text));
  select count(*) into v_open from public.agent_workspace_claims c
   where c.requested_by = v_uid and c.claimed_at is null and c.expires_at > v_now;
  if v_open >= 3 then raise exception 'agent_quota_reached'; end if;
  if exists (select 1 from public.workspaces w where w.slug = lower(p_slug)) then
    raise exception 'slug_taken';
  end if;

  insert into public.workspaces (name, slug, description, plan)
  values (p_name, lower(p_slug), nullif(p_description, ''), 'free')
  returning id into v_ws;

  insert into public.agent_workspace_claims (workspace_id, client_id, requested_by, token_hash, created_at, expires_at)
  values (v_ws, p_client_id, v_uid, p_token_hash, v_now, v_now + interval '48 hours');

  return query select v_ws, lower(p_slug), v_now + interval '48 hours';
end;
$function$

CREATE OR REPLACE FUNCTION public.rout_broadcast_event_allowed(p_owner uuid, p_event uuid, p_space text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare h text;
begin
 if p_owner is distinct from public.rout_current_user_id() then return false;end if;
 if p_space='root' then select username into h from public.profiles where id=p_owner;
 elsif p_space='alias' then select handle into h from public.alias_profiles where user_id=p_owner;
 else return false;end if;
 if h is null or not exists(select 1 from public.rout_qa_owner(h,p_space) where owner_id=p_owner) then return false;end if;
 return exists(select 1 from public.ephemeral_statuses where id=p_event and user_id=p_owner and space=p_space and status_type='micro_text' and expires_at>now())
 or exists(select 1 from public.profile_questions where id=p_event and owner_id=p_owner and space=p_space and published and not is_quarantined and answer is not null and story_until>now());
end $function$

CREATE OR REPLACE FUNCTION public.rout_claim_agent_workspace(p_token_hash text)
 RETURNS TABLE(workspace_id uuid, slug text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := public.rout_current_user_id();
  v_claim public.agent_workspace_claims%rowtype;
  v_slug text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_claim from public.agent_workspace_claims c where c.token_hash = p_token_hash for update;
  if not found then raise exception 'claim_not_found'; end if;
  if v_claim.claimed_at is not null then raise exception 'claim_used'; end if;
  if v_claim.expires_at <= now() then raise exception 'claim_expired'; end if;

  insert into public.workspace_members (workspace_id, user_id, role)
  values (v_claim.workspace_id, v_uid, 'owner')
  on conflict on constraint workspace_members_pkey do update set role = 'owner';
  update public.agent_workspace_claims c
     set claimed_at = now(), claimed_by = v_uid
   where c.workspace_id = v_claim.workspace_id;
  select w.slug into v_slug from public.workspaces w where w.id = v_claim.workspace_id;
  return query select v_claim.workspace_id, v_slug;
end;
$function$

CREATE OR REPLACE FUNCTION public.rout_notify_omni_job()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 if new.status='queued' and (tg_op='INSERT' or old.status is distinct from new.status) then
  perform pg_notify('new_omni_job', json_build_object('id',new.id)::text);
 end if;
 if tg_op='INSERT' or old.status is distinct from new.status then
  perform pg_notify('omni_job_changed',json_build_object('id',new.id,'userId',new.user_id)::text);
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.rout_omni_media(p_path text, p_viewer uuid DEFAULT NULL::uuid)
 RETURNS TABLE(object_key text, content_type text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare j public.omni_jobs; snapshot jsonb; b jsonb; i jsonb; profile record; media text;
begin
 select * into j from public.omni_jobs where status='ready'
  and (local_media_path=p_path or kinetic_preview_path=p_path) limit 1;
 if not found then return; end if;
 if p_viewer is distinct from public.rout_current_user_id() then p_viewer:=null; end if;
 if p_viewer is distinct from j.user_id then
  media:='/api/public/gallery-media?path=' || replace(p_path,'/','%2F');
  for profile in
   select p.blocks from public.profiles p
    where p.id=j.user_id and exists(select 1 from public.rout_qa_owner(p.username,'root'))
   union all
   select a.blocks from public.alias_profiles a
    where a.user_id=j.user_id and exists(select 1 from public.rout_qa_owner(a.handle,'alias'))
  loop
   snapshot:=profile.blocks;
   for b in select value from jsonb_array_elements(coalesce(snapshot,'[]'::jsonb)) loop
    if b->>'kind'<>'social_grid' or coalesce((b->>'hidden')::boolean,false)
     or (nullif(b->>'startsAt','') is not null and (b->>'startsAt')::timestamptz>now())
     or (nullif(b->>'expiresAt','') is not null and (b->>'expiresAt')::timestamptz<=now()) then continue; end if;
    for i in select value from jsonb_array_elements(coalesce((b->>'value')::jsonb->'items','[]'::jsonb)) loop
     if i->>'mediaUrl'=media or i->>'kineticPreviewUrl'=media then
      return query select 'users/'||p_path, case when p_path like '%.webm' then 'video/webm' else 'image/webp' end; return;
     end if;
    end loop;
   end loop;
  end loop;
  return;
 end if;
 return query select 'users/'||p_path, case when p_path like '%.webm' then 'video/webm' else 'image/webp' end;
end $function$

CREATE OR REPLACE FUNCTION public.rout_parent_approve_consent(p_token_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_user uuid;
begin
  update public.parent_authorizations set status = 'approved'
   where token = p_token_hash and action_type = 'consent' and status = 'pending' and expires_at > now()
   returning user_id into v_user;
  if v_user is null then
    return exists (select 1 from public.parent_authorizations where token = p_token_hash and action_type = 'consent' and status = 'approved');
  end if;
  update public.users set parent_consent_status = 'approved' where id = v_user;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.rout_parent_request_payment(p_user_id uuid, p_token_hash text, p_details jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_parent text;
begin
  select parent_email into v_parent from public.users where id = p_user_id and parent_email is not null;
  if v_parent is null then return null; end if;
  insert into public.parent_authorizations (user_id, token, action_type, product_details, expires_at)
  values (p_user_id, p_token_hash, 'payment', coalesce(p_details, '{}'::jsonb), now() + interval '48 hours');
  return v_parent;
end $function$

CREATE OR REPLACE FUNCTION public.rout_parent_set_qa_level(p_token_hash text, p_level qa_permission_level)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_user uuid;
begin
  select user_id into v_user from public.parent_authorizations
   where token = p_token_hash and action_type = 'consent' and (status = 'approved' or (status = 'pending' and expires_at > now()));
  if v_user is null then return false; end if;
  update public.users set qa_permission_level = p_level where id = v_user;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.rout_purge_unclaimed_agent_workspaces()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ids uuid[];
begin
  select coalesce(array_agg(c.workspace_id), '{}') into v_ids
    from (select workspace_id from public.agent_workspace_claims
           where claimed_at is null and expires_at <= now()
           order by expires_at
           limit 500
           for update skip locked) c;
  if cardinality(v_ids) = 0 then return 0; end if;

  delete from public.oauth_clients where workspace_id = any (v_ids);
  delete from public.tracked_qrs where workspace_id = any (v_ids);
  delete from public.bookings where workspace_id = any (v_ids);
  delete from public.workspace_transfers where workspace_id = any (v_ids);
  delete from public.workspaces where id = any (v_ids);
  return cardinality(v_ids);
end;
$function$

CREATE OR REPLACE FUNCTION public.rout_qa_charge(p_recipient uuid, p_abuse_key text, p_net text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id bigint;
  v_net text := case when p_net ~ '^[0-9a-f]{64}$' then p_net end;
  v_score integer;
  v_start timestamptz := now() + make_interval(mins => 720 + floor(random() * 2161)::int);
begin
  if p_abuse_key is null or p_abuse_key !~ '^[0-9a-f]{64}$' then return; end if;
  insert into public.qa_trust_charges (recipient_id, sender_key, muter_net) values (p_recipient, p_abuse_key, v_net)
  on conflict (recipient_id, sender_key) where sender_key is not null do nothing
  returning id into v_id;
  if v_id is null then return; end if;
  if exists (select 1 from public.qa_trust_charges c
              where c.sender_key = p_abuse_key and c.id <> v_id and c.charged_at > now() - interval '24 hours') then
    return;
  end if;
  if v_net is not null and exists (select 1 from public.qa_trust_charges c
              where c.sender_key = p_abuse_key and c.id <> v_id and c.muter_net = v_net
                and c.charged_at > now() - interval '7 days') then
    return;
  end if;
  insert into public.qa_guest_trust as g (sender_key, trust_score) values (p_abuse_key, 80)
  on conflict (sender_key) do update set trust_score = greatest(0, g.trust_score - 20), updated_at = now()
  returning g.trust_score into v_score;
  if v_score < 50 then
    update public.qa_guest_trust g
       set ban_starts_at = v_start, ban_until = v_start + interval '7 days', updated_at = now()
     where g.sender_key = p_abuse_key and (g.ban_until is null or g.ban_until < now());
  end if;
end $function$

CREATE OR REPLACE FUNCTION public.rout_qa_maintenance()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_abuse int; v_quar int; v_charges int; v_healed int; v_users int; v_rl int;
begin
  update public.profile_questions set abuse_key = null, abuse_key_until = null
   where abuse_key is not null and abuse_key_until < now();
  get diagnostics v_abuse = row_count;
  delete from public.profile_questions
   where is_quarantined and quarantine_reason in ('local_mute', 'global_ban') and created_at < now() - interval '30 days';
  get diagnostics v_quar = row_count;
  delete from public.qa_trust_charges where charged_at < now() - interval '90 days';
  get diagnostics v_charges = row_count;
  update public.qa_guest_trust set trust_score = least(100, trust_score + 10), updated_at = now()
   where trust_score < 100 and updated_at < now() - interval '7 days';
  get diagnostics v_healed = row_count;
  delete from public.qa_guest_trust where trust_score >= 100 and (ban_until is null or ban_until < now());
  update public.users set trust_score = least(100, trust_score + 10), trust_healed_at = now()
   where trust_score < 100 and coalesce(trust_healed_at, '-infinity'::timestamptz) < now() - interval '7 days';
  get diagnostics v_users = row_count;
  delete from public.rate_limits where window_start < now() - interval '1 day';
  get diagnostics v_rl = row_count;
  return jsonb_build_object('abuseKeysExpired', v_abuse, 'quarantineDeleted', v_quar, 'chargesExpired', v_charges,
                            'guestsHealed', v_healed, 'usersHealed', v_users, 'rateLimitsDeleted', v_rl);
end $function$

CREATE OR REPLACE FUNCTION public.rout_qa_mute_by_message(p_message_id uuid, p_muter_net text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := public.rout_current_user_id();
  q record;
  v_action uuid;
begin
  if v_me is null then return false; end if;
  select owner_id, space, sender_key, sender_acct_key, abuse_key, abuse_key_until into q
    from public.profile_questions where id = p_message_id;
  if not found or q.owner_id <> v_me then return false; end if;
  if exists (select 1 from public.qa_mute_actions a where a.recipient_id = v_me and a.source_question_id = p_message_id) then
    return true;
  end if;
  insert into public.qa_mute_actions (recipient_id, source_question_id) values (v_me, p_message_id) returning id into v_action;
  if q.sender_key is not null then
    insert into public.shadow_mutes (recipient_id, action_id, muted_sender_key, space) values (v_me, v_action, q.sender_key, q.space);
  end if;
  if q.sender_acct_key is not null and q.sender_acct_key is distinct from q.sender_key then
    insert into public.shadow_mutes (recipient_id, action_id, muted_sender_key, space) values (v_me, v_action, q.sender_acct_key, q.space);
  end if;
  if q.abuse_key is not null and q.abuse_key_until > now() then
    perform public.rout_qa_charge(v_me, q.abuse_key, p_muter_net);
  end if;
  update public.profile_questions
     set is_quarantined = true, quarantine_reason = 'muted_by_owner', published = false
   where id = p_message_id;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.rout_qa_submit(p_handle text, p_space text, p_body text, p_device_base text, p_acct_base text, p_abuse_now text, p_abuse_prev text, p_masked boolean)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  o record;
  v_sender uuid := public.rout_current_user_id();
  v_dev text;
  v_acct text;
  v_abuse text := case when p_abuse_now ~ '^[0-9a-f]{64}$' then p_abuse_now end;
  v_abuse_prev text := case when p_abuse_prev ~ '^[0-9a-f]{64}$' then p_abuse_prev end;
  v_prompt text;
  v_local boolean;
  v_global boolean;
  v_reason text;
  v_level text;
begin
  if p_space not in ('root', 'alias') then return 'not_found'; end if;
  if p_body is null or char_length(p_body) not between 1 and 300 then return 'invalid'; end if;
  select * into o from public.rout_qa_owner(p_handle, p_space);
  if o.owner_id is null or not coalesce((o.prefs ->> 'questionsEnabled')::boolean, false) then return 'not_found'; end if;
  v_level := coalesce(o.prefs->>'qaAudience', 'members_only');
  if v_level not in ('public_unrestricted', 'members_only', 'verified_only') then return 'not_found'; end if;
  if v_level <> 'public_unrestricted' and v_sender is null then return 'not_found'; end if;
  if v_level = 'verified_only' and not exists (select 1 from public.profiles where id=v_sender and verified is true) then return 'not_found'; end if;
  if exists (select 1 from public.users where id=o.owner_id and qa_permission_level='disabled') then return 'not_found'; end if;
  if exists (select 1 from public.users where id=o.owner_id and qa_permission_level='verified_only') and not exists (select 1 from public.profiles where id=v_sender and verified is true) then return 'not_found'; end if;
  if exists (select 1 from public.users where id=o.owner_id and qa_permission_level='members_only') and v_sender is null then return 'not_found'; end if;
  v_prompt := nullif(left(btrim(coalesce(
    case when o.prefs ->> 'qaPrompt' = 'custom' then o.prefs ->> 'qaPromptCustom' end,
    o.prefs ->> 'qaPrompt')), 120), '');

  v_dev := public.rout_qa_scope_key(p_device_base, o.owner_id, p_space);
  v_acct := case when v_sender is not null then public.rout_qa_scope_key(p_acct_base, o.owner_id, p_space) end;

  -- Both checks always run, whatever the first one finds.
  v_local := exists (select 1 from public.shadow_mutes m
                      where m.recipient_id = o.owner_id
                        and (m.space is null or m.space = p_space)
                        and ((m.muted_sender_key is not null and m.muted_sender_key in (v_dev, v_acct))
                          or (v_sender is not null and m.space is null and m.muted_sender_id = v_sender)));
  v_global := exists (select 1 from public.users u
                       where u.id = v_sender and u.global_shadow_ban_starts_at <= now() and u.global_shadow_ban_until > now())
           or exists (select 1 from public.profiles p where p.id = v_sender and coalesce(p.is_shadowbanned, false))
           or exists (select 1 from public.qa_guest_trust g
                       where g.sender_key in (v_abuse, v_abuse_prev) and g.ban_starts_at <= now() and g.ban_until > now());
  v_reason := case when v_local then 'local_mute' when v_global then 'global_ban' end;

  insert into public.profile_questions
    (owner_id, space, body, prompt, sender_key, sender_acct_key, abuse_key, abuse_key_until,
     is_quarantined, quarantine_reason, style_masked, visible_after)
  values
    (o.owner_id, p_space, p_body, v_prompt, v_dev, v_acct, v_abuse,
     case when v_abuse is not null then now() + interval '7 days' end,
     v_reason is not null, v_reason, coalesce(p_masked, false),
     now() + make_interval(secs => 120 + floor(random() * 481)::int));
  return 'ok';
end $function$

CREATE OR REPLACE FUNCTION public.rout_qa_unmute(p_action_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := public.rout_current_user_id();
  v_source uuid;
begin
  if v_me is null then return false; end if;
  delete from public.qa_mute_actions where id = p_action_id and recipient_id = v_me
  returning source_question_id into v_source;
  if not found then return false; end if;
  if v_source is not null then
    update public.profile_questions
       set is_quarantined = false, quarantine_reason = null
     where id = v_source and owner_id = v_me and quarantine_reason = 'muted_by_owner';
  end if;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.rout_record_signup_age(p_email text, p_dob date, p_parent_email text, p_token_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_minor boolean;
begin
  select id into v_id from public.users
   where lower(email) = lower(p_email) and date_of_birth is null and created_at > now() - interval '15 minutes'
   limit 1;
  if v_id is null then return null; end if;
  v_minor := p_dob > (current_date - interval '16 years');
  update public.users
     set date_of_birth = p_dob,
         parent_email = case when v_minor then lower(p_parent_email) else null end,
         parent_consent_status = case when v_minor then 'pending'::public.parent_consent_status else 'none' end
   where id = v_id;
  if v_minor and p_token_hash is not null then
    insert into public.parent_authorizations (user_id, token, action_type, expires_at)
    values (v_id, p_token_hash, 'consent', now() + interval '30 days');
  end if;
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.rout_shadow_mute_trust()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_score integer;
  v_new integer;
  v_start timestamptz := now() + make_interval(mins => 720 + floor(random() * 2161)::int);
begin
  if new.muted_sender_id is not null then
    insert into public.qa_trust_charges (recipient_id, sender_user_id) values (new.recipient_id, new.muted_sender_id)
    on conflict (recipient_id, sender_user_id) where sender_user_id is not null do nothing;
    get diagnostics v_new = row_count;
    if v_new = 0 then return new; end if;
    update public.users u
       set trust_score = greatest(0, u.trust_score - 20)
     where u.id = new.muted_sender_id
     returning u.trust_score into v_score;
    if v_score is not null and v_score < 50 then
      update public.users u
         set global_shadow_ban_starts_at = v_start,
             global_shadow_ban_until = v_start + interval '7 days'
       where u.id = new.muted_sender_id
         and (u.global_shadow_ban_until is null or u.global_shadow_ban_until < now());
    end if;
  elsif new.muted_sender_key is not null then
    insert into public.qa_trust_charges (recipient_id, sender_key) values (new.recipient_id, new.muted_sender_key)
    on conflict (recipient_id, sender_key) where sender_key is not null do nothing;
    get diagnostics v_new = row_count;
    if v_new = 0 then return new; end if;
    insert into public.qa_guest_trust as g (sender_key, trust_score)
         values (new.muted_sender_key, 80)
    on conflict (sender_key) do update
         set trust_score = greatest(0, g.trust_score - 20), updated_at = now()
    returning g.trust_score into v_score;
    if v_score < 50 then
      update public.qa_guest_trust g
         set ban_starts_at = v_start, ban_until = v_start + interval '7 days', updated_at = now()
       where g.sender_key = new.muted_sender_key
         and (g.ban_until is null or g.ban_until < now());
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.rout_subscriber_join(p_handle text, p_hash text, p_ciphertext text, p_iv text, p_confirm_hash text, p_unsubscribe_hash text, p_locale text)
 RETURNS TABLE(outcome text, out_owner uuid, out_space text, out_list integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
#variable_conflict use_column
declare
  v_owner uuid;
  v_space text;
  v_blocks jsonb;
  v_has_block boolean;
  v_list integer;
  v_status text;
begin
  select p.id, 'root', p.blocks into v_owner, v_space, v_blocks
    from public.profiles p
   where lower(p.username) = lower(p_handle) and coalesce(p.status, 'active') = 'active'
   limit 1;
  if v_owner is null then
    select a.user_id, 'alias', a.blocks into v_owner, v_space, v_blocks
      from public.alias_profiles a where lower(a.handle) = lower(p_handle) limit 1;
  end if;
  if v_owner is null then
    return query select 'not_found'::text, null::uuid, null::text, null::integer;
    return;
  end if;

  select true, nullif(left(regexp_replace(coalesce(b->>'value', ''), '\D', '', 'g'), 9), '')::integer
    into v_has_block, v_list
    from jsonb_array_elements(case when jsonb_typeof(v_blocks) = 'array' then v_blocks else '[]'::jsonb end) b
   where b->>'kind' = 'newsletter' and coalesce(b->>'hidden', 'false') <> 'true'
   limit 1;
  if v_has_block is not true then
    return query select 'no_block'::text, null::uuid, null::text, null::integer;
    return;
  end if;

  select s.status into v_status from public.profile_subscribers s
   where s.owner_user_id = v_owner and s.space = v_space and s.email_hash = p_hash;
  if v_status = 'confirmed' then
    return query select 'already'::text, v_owner, v_space, v_list;
    return;
  end if;

  insert into public.profile_subscribers as s
    (owner_user_id, handle, space, email_hash, email_ciphertext, email_iv, status,
     confirm_token_hash, unsubscribe_token_hash, locale, brevo_list_id)
  values (v_owner, lower(p_handle), v_space, p_hash, p_ciphertext, p_iv, 'pending',
     p_confirm_hash, p_unsubscribe_hash, nullif(left(coalesce(p_locale, ''), 10), ''), v_list)
  on conflict (owner_user_id, space, email_hash) do update set
    handle = excluded.handle,
    email_ciphertext = excluded.email_ciphertext,
    email_iv = excluded.email_iv,
    status = 'pending',
    confirm_token_hash = excluded.confirm_token_hash,
    unsubscribe_token_hash = excluded.unsubscribe_token_hash,
    locale = excluded.locale,
    brevo_list_id = excluded.brevo_list_id,
    unsubscribed_at = null,
    updated_at = now();
  return query select 'pending'::text, v_owner, v_space, v_list;
end $function$

CREATE OR REPLACE FUNCTION public.rout_users_minor_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.is_minor := new.date_of_birth is not null and new.date_of_birth > (current_date - interval '16 years');
  if new.date_of_birth is not null and new.date_of_birth > (current_date - interval '18 years')
     and (tg_op = 'INSERT' or old.date_of_birth is distinct from new.date_of_birth) then
    new.qa_permission_level := 'verified_only';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.save_profile_draft(p_user_id uuid, p_space text, p_payload jsonb, p_expected_revision bigint)
 RETURNS TABLE(revision bigint, published_revision bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_current bigint;
begin
  if p_space not in ('verified', 'alias') then
    raise exception 'draft_space_invalid';
  end if;

  select d.revision into v_current
    from public.profile_drafts d
   where d.user_id = p_user_id and d.space = p_space
   for update;

  if v_current is null then
    if p_expected_revision <> 0 then raise exception 'draft_conflict'; end if;
    insert into public.profile_drafts (user_id, space, payload, revision)
    values (p_user_id, p_space, p_payload, 1);
  else
    if v_current <> p_expected_revision then raise exception 'draft_conflict'; end if;
    update public.profile_drafts d
       set payload = p_payload, revision = d.revision + 1, updated_at = now()
     where d.user_id = p_user_id and d.space = p_space;
  end if;

  return query
    select d.revision, d.published_revision
      from public.profile_drafts d
     where d.user_id = p_user_id and d.space = p_space;
end;
$function$

CREATE OR REPLACE FUNCTION public.security_audit_chain()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  prev text;
begin
  perform pg_advisory_xact_lock(727001);
  select current_hash into prev from public.security_audit_logs order by id desc limit 1;
  if prev is null then
    select last_hash into prev from public.security_audit_checkpoints order by day desc limit 1;
  end if;
  new.prev_hash := coalesce(prev, repeat('0', 64));
  new.created_at := date_trunc('milliseconds', coalesce(new.created_at, now()));
  new.current_hash := encode(sha256(convert_to(
    new.prev_hash || '|' || new.event_type || '|' || coalesce(new.user_id, '') || '|' ||
    coalesce(new.actor_id, '') || '|' || new.payload_json::text || '|' ||
    to_char(new.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'UTF8')), 'hex');
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.security_audit_refuse()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' and tg_table_name = 'security_audit_logs' then
    if current_setting('rout.audit_retention',true) = 'on' and old.created_at < now() - interval '365 days' then return old; end if;
    if current_setting('rout.purge_user_id',true) = old.user_id and exists (
      select 1 from public.account_deletions d where d.user_id::text=old.user_id
      and d.cancelled_at is null and d.completed_at is null and d.purge_after<=now()
    ) then return old; end if;
  end if;
  raise exception 'security audit tables are append-only (% refused)', tg_op;
end $function$

CREATE OR REPLACE FUNCTION public.signin_guard_record(_identity_hash text, _success boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.signin_throttle; new_failures int; lock_for interval;
begin
  if _identity_hash is null or length(_identity_hash) not between 16 and 128 then
    return jsonb_build_object('locked', false, 'retry_after', 0);
  end if;

  if _success then
    delete from public.signin_throttle where identity_hash = _identity_hash;
    return jsonb_build_object('locked', false, 'retry_after', 0);
  end if;

  select * into r from public.signin_throttle where identity_hash = _identity_hash for update;

  if r.identity_hash is null or r.window_started_at < now() - interval '15 minutes' then
    insert into public.signin_throttle (identity_hash, failures, window_started_at, locked_until)
    values (_identity_hash, 1, now(), null)
    on conflict (identity_hash) do update
      set failures = 1, window_started_at = now(), locked_until = null;
    return jsonb_build_object('locked', false, 'retry_after', 0);
  end if;

  new_failures := r.failures + 1;
  lock_for := case
    when new_failures >= 10 then interval '15 minutes'
    when new_failures >= 7 then interval '5 minutes'
    when new_failures >= 5 then interval '1 minute'
    else null end;

  update public.signin_throttle
     set failures = new_failures,
         locked_until = case when lock_for is null then null else now() + lock_for end
   where identity_hash = _identity_hash;

  delete from public.signin_throttle
   where window_started_at < now() - interval '1 day'
     and (locked_until is null or locked_until < now());

  if lock_for is null then
    return jsonb_build_object('locked', false, 'retry_after', 0);
  end if;
  return jsonb_build_object('locked', true,
    'retry_after', ceil(extract(epoch from lock_for))::int);
end;
$function$

CREATE OR REPLACE FUNCTION public.signin_guard_status(_identity_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.signin_throttle;
begin
  select * into r from public.signin_throttle where identity_hash = _identity_hash;
  if r.identity_hash is null or r.locked_until is null or r.locked_until <= now() then
    return jsonb_build_object('locked', false, 'retry_after', 0);
  end if;
  return jsonb_build_object('locked', true,
    'retry_after', greatest(1, ceil(extract(epoch from (r.locked_until - now())))::int));
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_public_feedback(p_form uuid, p_rating integer, p_comment text, p_name text, p_consent boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare f public.feedback_forms; result uuid;
begin
  select * into f from public.feedback_forms where id=p_form;
  if not found or not public.feedback_form_is_public(f) then raise exception 'feedback_unavailable'; end if;
  if char_length(coalesce(p_comment,'')) > 2000 or char_length(coalesce(p_name,'')) > 100 then
    raise exception 'feedback_invalid';
  end if;
  if (f.type='text_review' and (p_rating is not null or char_length(trim(coalesce(p_comment,'')))=0))
    or (f.type<>'text_review' and (p_rating is null or
      p_rating < case when f.type='nps_10' then 0 else 1 end or
      p_rating > case when f.type='nps_10' then 10 when f.type='emoji_3' then 3 else 5 end)) then
    raise exception 'feedback_invalid';
  end if;
  insert into public.feedback_responses(form_id,rating,comment,reviewer_name,allow_featured)
    values(p_form,p_rating,nullif(trim(p_comment),''),nullif(trim(p_name),''),coalesce(p_consent,false)) returning id into result;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.sync_omni_semantic_draft()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare b jsonb; config jsonb; item jsonb; card uuid; path text; kept uuid[]:='{}';
begin
 for b in select value from jsonb_array_elements(coalesce(new.payload->'blocks','[]'::jsonb)) loop
  if b->>'kind'<>'social_grid' then continue; end if;
  begin config:=(b->>'value')::jsonb; exception when invalid_text_representation then continue; end;
  if jsonb_typeof(config->'items') is distinct from 'array' then continue; end if;
  for item in select value from jsonb_array_elements(config->'items') limit 30 loop
   path:=public.rout_grid_media_path(item->>'mediaUrl');
   if path is null or split_part(path,'/',1)<>new.user_id::text then continue; end if;
   select id into card from public.social_grid_items where user_id=new.user_id and profile_space=new.space
    and block_id=b->>'id' and source_item_id=item->>'id' limit 1;
   if card is null then continue; end if;
   insert into public.omni_matrix_items(id,user_id,profile_space,block_id,source_item_id,content_type,image_path,
    target_url,title,meta_tag,is_hero,kinetic_preview_path,created_at)
   values(card,new.user_id,new.space,b->>'id',item->>'id',
    (case when item->>'contentType' in ('article','podcast','program','short','event','social') then item->>'contentType' else 'social' end)::public.omni_content_type,
    path,nullif(item->>'targetUrl',''),left(coalesce(item->>'caption',''),150),left(nullif(item->>'metaTag',''),40),
    coalesce(item->'isHero'='true'::jsonb,false),
    case when public.rout_grid_media_path(item->>'kineticPreviewUrl') ~ '^[0-9a-f-]{36}/omni-[A-Za-z0-9._-]+\.webm$'
      and split_part(public.rout_grid_media_path(item->>'kineticPreviewUrl'),'/',1)=new.user_id::text
      then public.rout_grid_media_path(item->>'kineticPreviewUrl') else null end,
    coalesce(nullif(item->>'createdAt','')::timestamptz,now()))
   on conflict(id) do update set content_type=excluded.content_type,image_path=excluded.image_path,
    target_url=excluded.target_url,title=excluded.title,meta_tag=excluded.meta_tag,
    is_hero=excluded.is_hero,kinetic_preview_path=excluded.kinetic_preview_path;
   kept:=array_append(kept,card);
  end loop;
 end loop;
 delete from public.omni_matrix_items where user_id=new.user_id and profile_space=new.space and not(id=any(kept));
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.sync_social_grid_draft()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  b jsonb;
  config jsonb;
  item jsonb;
  ordinal bigint;
  kept uuid[] := '{}';
  card_id uuid;
begin
  for b in select value from jsonb_array_elements(coalesce(new.payload->'blocks','[]'::jsonb)) loop
    if b->>'kind' <> 'social_grid' then continue; end if;
    begin
      config := (b->>'value')::jsonb;
    exception when invalid_text_representation then
      continue;
    end;
    if jsonb_typeof(config->'items') <> 'array' then continue; end if;
    for item, ordinal in select value, ordinality from jsonb_array_elements(config->'items') with ordinality loop
      if ordinal > 30 or coalesce(item->>'id','') = '' or coalesce(item->>'mediaUrl','') = '' then continue; end if;
      insert into public.social_grid_items
        (user_id, profile_space, block_id, source_item_id, platform, media_url, caption, target_url, is_pinned, is_video, position, created_at)
      values (new.user_id, new.space, b->>'id', item->>'id',
        case when item->>'platform' in ('instagram','tiktok','article','custom') then item->>'platform' else 'custom' end,
        item->>'mediaUrl', coalesce(item->>'caption',''), nullif(item->>'targetUrl',''),
        coalesce(item->'pinned' = 'true'::jsonb,false), coalesce(item->'isVideo' = 'true'::jsonb,false),
        ordinal - 1, coalesce(nullif(item->>'createdAt','')::timestamptz, now()))
      on conflict (user_id, profile_space, block_id, source_item_id) do update set
        platform=excluded.platform, media_url=excluded.media_url, caption=excluded.caption,
        target_url=excluded.target_url, is_pinned=excluded.is_pinned, is_video=excluded.is_video,
        position=excluded.position
      returning id into card_id;
      kept := array_append(kept, card_id);
    end loop;
  end loop;
  delete from public.social_grid_items
    where user_id=new.user_id and profile_space=new.space and not (id = any(kept));
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.validate_ephemeral_presence()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare p jsonb := new.content_payload; q record;
begin
 if jsonb_typeof(p) is distinct from 'object' or octet_length(p::text)>4096 then raise exception 'invalid_status_payload'; end if;
 if new.status_type='micro_text' then
  if jsonb_typeof(p->'text') is distinct from 'string' or char_length(btrim(p->>'text')) not between 1 and 280
   or coalesce(p->>'theme','aurora') not in ('aurora','glass')
   or (p ? 'theme' and jsonb_typeof(p->'theme') is distinct from 'string')
   or coalesce(p->>'bg','none') not in ('none','sunset','ocean','forest','noir','candy','gold')
   or coalesce(p->>'font','classic') not in ('classic','display','mono','hand')
   or coalesce(p->>'align','center') not in ('left','center','right')
   or (p ? 'sticker' and (jsonb_typeof(p->'sticker') is distinct from 'string' or char_length(p->>'sticker') not between 1 and 8))
   or exists(select 1 from jsonb_object_keys(p) k where k not in ('text','theme','bg','font','align','sticker')) then raise exception 'invalid_micro_text'; end if;
 elsif new.status_type='omni_drop' then
  if jsonb_typeof(p->'blockId') is distinct from 'string' or char_length(p->>'blockId') not between 1 and 100
   or (p ? 'itemId' and (jsonb_typeof(p->'itemId') is distinct from 'string' or char_length(p->>'itemId') not between 1 and 100))
   or exists(select 1 from jsonb_object_keys(p) k where k not in ('blockId','itemId')) then raise exception 'invalid_omni_drop'; end if;
 else
  if jsonb_typeof(p->'questionId') is distinct from 'string' or exists(select 1 from jsonb_object_keys(p) k where k<>'questionId') then raise exception 'invalid_qa_reference'; end if;
  select owner_id,space,answered_at,story_until into q from public.profile_questions
   where id=(p->>'questionId')::uuid and owner_id=new.user_id and published and answer is not null and not is_quarantined;
  if not found or q.space<>new.space or q.story_until is null then raise exception 'invalid_qa_reference'; end if;
 end if;
 if tg_op='INSERT' then new.created_at:=now(); new.expires_at:=now()+interval '24 hours';
 else new.created_at:=old.created_at;new.expires_at:=old.expires_at;
  if new.user_id<>old.user_id or new.space<>old.space or new.status_type<>old.status_type then raise exception 'immutable_status_identity'; end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.wallet_credit(_user_id uuid, _amount_cents integer, _kind text DEFAULT 'topup'::text, _description text DEFAULT NULL::text, _reference text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  _balance integer;
begin
  if _amount_cents is null or _amount_cents <= 0 then
    raise exception 'wallet_credit: amount must be positive';
  end if;
  if _kind not in ('topup', 'refund', 'adjustment') then
    raise exception 'wallet_credit: invalid kind %', _kind;
  end if;

  insert into public.wallets (user_id) values (_user_id)
  on conflict (user_id) do nothing;

  -- Rijvergrendeling: parallelle webhooks wachten netjes op elkaar.
  select balance_cents into _balance
    from public.wallets where user_id = _user_id for update;

  begin
    insert into public.wallet_transactions
      (user_id, kind, amount_cents, description, reference)
    values (_user_id, _kind, _amount_cents, _description, _reference);
  exception when unique_violation then
    -- Zelfde Stripe-referentie: al geboekt, saldo ongewijzigd.
    return _balance;
  end;

  update public.wallets
     set balance_cents = balance_cents + _amount_cents
   where user_id = _user_id
   returning balance_cents into _balance;

  return _balance;
end $function$

CREATE OR REPLACE FUNCTION public.wallet_debit(_user_id uuid, _amount_cents integer, _description text DEFAULT NULL::text, _reference text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  _balance integer;
begin
  if _amount_cents is null or _amount_cents <= 0 then
    raise exception 'wallet_debit: amount must be positive';
  end if;

  insert into public.wallets (user_id) values (_user_id)
  on conflict (user_id) do nothing;

  select balance_cents into _balance
    from public.wallets where user_id = _user_id for update;

  if _balance is null or _balance < _amount_cents then
    return -1; -- onvoldoende saldo; niets geboekt
  end if;

  begin
    insert into public.wallet_transactions
      (user_id, kind, amount_cents, description, reference)
    values (_user_id, 'relay_fee', -_amount_cents, _description, _reference);
  exception when unique_violation then
    return _balance; -- deze periode al afgeschreven
  end;

  update public.wallets
     set balance_cents = balance_cents - _amount_cents
   where user_id = _user_id
   returning balance_cents into _balance;

  return _balance;
end $function$

CREATE OR REPLACE FUNCTION public.wt_assert(ok boolean, msg text)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
begin
  if not coalesce(ok, false) then
    raise exception '%', msg using errcode = 'P0001';
  end if;
  return true;
end $function$
